#!/usr/bin/env node

import { realpath } from 'node:fs/promises';

import {
  normalizeEntries,
  readTailRecordsBounded,
  type Runtime,
} from '../../../shared/transcript/runtimes.js';
import {
  ClassificationCache,
  discover,
} from '../../session-observer/src/lib/locate.js';
import type { TranscriptCandidate } from '../../session-observer/src/lib/types.js';
import type { GuidanceProvider } from './guidance-capabilities.js';
import {
  discoverGuidanceCandidates,
  discoverGuidance,
  GuidanceDiscoveryError,
  GUIDANCE_DISCOVERY_OPTIONS,
  readGuidanceCodexNativeId,
  selectGuidanceCandidate,
  type GuidanceQualifiedSessionId,
  type GuidanceSessionCandidate,
} from './guidance-discovery.js';
import { prepareForkGuidance, type GuidanceEntryPoint } from './guidance.js';
import { sanitizePreviewConversationEntries } from './preview.js';
import {
  applySessionImport,
  planSessionImport,
  SessionImportError,
  type SessionImportInput,
} from './session-import.js';

export interface GuidanceCliIo {
  stdout: (value: string) => void;
  stderr: (value: string) => void;
}

export interface GuidanceCliDependencies {
  import?: (
    input: SessionImportInput,
    expectedDigest?: string,
  ) => Promise<unknown>;
  discover: (
    source: string,
    provider: 'claude' | 'codex' | 'cursor' | 'all',
  ) => Promise<unknown>;
  preview: (
    source: string,
    session: GuidanceQualifiedSessionId,
  ) => Promise<unknown>;
  prepare: (
    source: string,
    target: string,
    session: GuidanceQualifiedSessionId,
    entryPoint: GuidanceEntryPoint,
  ) => Promise<unknown>;
}

const HELP = `session-fork-to-destination — EXPERIMENTAL / NOT RELEASED

Read-only discovery and destination-tab fork guidance. Preparing guidance does not
run a provider, create a fork, authenticate, or modify provider session stores.

Usage:
  session-fork-to-destination discover --source PATH [--provider claude|codex|cursor|all] [--json]
  session-fork-to-destination preview --source PATH --session PROVIDER:SURFACE:ID [--json]
  session-fork-to-destination prepare --source PATH --target PATH --session PROVIDER:SURFACE:ID \\
    --entry-point source-current|source-other|destination-fresh [--json]
  session-fork-to-destination import --source PATH --target PATH --session PROVIDER:cli:UUID \\
    --to codex|claude --entry-point source-other|destination-fresh [--target-home PATH] [--json] \\
    [--apply --expect-plan SHA256]

Import defaults to a read-only plan. Apply imports a seed; native fork not created.
Raw supported conversation and tool payloads may contain secrets.
`;

class GuidanceCliArgumentError extends Error {
  readonly code = 'invalid-arguments';
}

interface Flags {
  command: 'discover' | 'preview' | 'prepare' | 'import';
  values: Map<string, string>;
  json: boolean;
  apply: boolean;
}

const VALUE_FLAGS = new Set([
  '--source',
  '--target',
  '--session',
  '--provider',
  '--entry-point',
  '--to',
  '--target-home',
  '--expect-plan',
]);

function parse(argv: readonly string[]): Flags {
  const command = argv[0];
  if (!['discover', 'preview', 'prepare', 'import'].includes(command)) {
    throw new GuidanceCliArgumentError();
  }
  const values = new Map<string, string>();
  let json = false;
  let apply = false;
  for (let index = 1; index < argv.length; index += 1) {
    const flag = argv[index];
    if (flag === '--apply') {
      if (apply || command !== 'import') throw new GuidanceCliArgumentError();
      apply = true;
      continue;
    }
    if (flag === '--json') {
      if (json) throw new GuidanceCliArgumentError();
      json = true;
      continue;
    }
    if (!VALUE_FLAGS.has(flag) || values.has(flag)) {
      throw new GuidanceCliArgumentError();
    }
    const flagValue = argv[index + 1];
    if (
      flagValue === undefined ||
      flagValue.startsWith('--') ||
      flagValue.length === 0
    ) {
      throw new GuidanceCliArgumentError();
    }
    values.set(flag, flagValue);
    index += 1;
  }
  return { command: command as Flags['command'], values, json, apply };
}

function required(flags: Flags, name: string): string {
  const result = flags.values.get(name);
  if (result === undefined) throw new GuidanceCliArgumentError();
  return result;
}

function allowOnly(flags: Flags, allowed: readonly string[]): void {
  if ([...flags.values.keys()].some((key) => !allowed.includes(key))) {
    throw new GuidanceCliArgumentError();
  }
}

function provider(flags: Flags): 'claude' | 'codex' | 'cursor' | 'all' {
  const result = flags.values.get('--provider') ?? 'all';
  if (!['claude', 'codex', 'cursor', 'all'].includes(result)) {
    throw new GuidanceCliArgumentError();
  }
  return result as 'claude' | 'codex' | 'cursor' | 'all';
}

function session(flags: Flags): GuidanceQualifiedSessionId {
  const result = required(flags, '--session');
  if (
    !/^(?:claude|codex|cursor):(?:cli|ide|ambiguous):[^:\s]+$/u.test(result) ||
    [...result].some((character) => character.codePointAt(0)! < 32)
  ) {
    throw new GuidanceCliArgumentError();
  }
  return result as GuidanceQualifiedSessionId;
}

function entryPoint(flags: Flags): GuidanceEntryPoint {
  const result = required(flags, '--entry-point');
  if (
    !['source-current', 'source-other', 'destination-fresh'].includes(result)
  ) {
    throw new GuidanceCliArgumentError();
  }
  return result as GuidanceEntryPoint;
}

function errorCode(error: unknown): string {
  if (error instanceof GuidanceCliArgumentError) return error.code;
  if (error !== null && typeof error === 'object') {
    const code = (error as { code?: unknown }).code;
    if (typeof code === 'string' && /^[a-z][a-z0-9-]*$/u.test(code))
      return code;
  }
  return 'unexpected-failure';
}

function errorProvenance(error: unknown) {
  return error instanceof GuidanceDiscoveryError &&
    error.provider !== undefined &&
    error.reason !== undefined
    ? { provider: error.provider, reason: error.reason }
    : {};
}

function render(
  io: GuidanceCliIo,
  command: Flags['command'],
  data: unknown,
  json: boolean,
): void {
  const envelope = {
    ok: true,
    command,
    status: 'experimental-not-released',
    currentSelection: 'explicit-required',
    noForkCreated: true,
    data,
  };
  io.stdout(`${JSON.stringify(envelope, null, json ? 0 : 2)}\n`);
}

export async function runGuidanceCli(
  argv: readonly string[],
  dependencies: GuidanceCliDependencies = DEFAULT_DEPENDENCIES,
  io: GuidanceCliIo = {
    stdout: (value) => process.stdout.write(value),
    stderr: (value) => process.stderr.write(value),
  },
): Promise<number> {
  if (argv.length === 1 && (argv[0] === '--help' || argv[0] === '-h')) {
    io.stdout(HELP);
    return 0;
  }
  let flags: Flags | undefined;
  try {
    flags = parse(argv);
    let data: unknown;
    if (flags.command === 'discover') {
      allowOnly(flags, ['--source', '--provider']);
      data = await dependencies.discover(
        required(flags, '--source'),
        provider(flags),
      );
    } else if (flags.command === 'preview') {
      allowOnly(flags, ['--source', '--session']);
      data = await dependencies.preview(
        required(flags, '--source'),
        session(flags),
      );
    } else if (flags.command === 'import') {
      allowOnly(flags, [
        '--source',
        '--target',
        '--session',
        '--entry-point',
        '--to',
        '--target-home',
        '--expect-plan',
      ]);
      if (flags.apply !== flags.values.has('--expect-plan'))
        throw new GuidanceCliArgumentError();
      const to = required(flags, '--to');
      if (to !== 'codex' && to !== 'claude')
        throw new GuidanceCliArgumentError();
      const input: SessionImportInput = {
        sourcePath: required(flags, '--source'),
        destinationPath: required(flags, '--target'),
        session: session(flags),
        to,
        entryPoint: entryPoint(flags),
        ...(flags.values.has('--target-home')
          ? { targetHome: required(flags, '--target-home') }
          : {}),
      };
      const digest = flags.apply ? required(flags, '--expect-plan') : undefined;
      data = await (dependencies.import ?? defaultImport)(input, digest);
    } else {
      allowOnly(flags, ['--source', '--target', '--session', '--entry-point']);
      data = await dependencies.prepare(
        required(flags, '--source'),
        required(flags, '--target'),
        session(flags),
        entryPoint(flags),
      );
    }
    render(io, flags.command, data, flags.json);
    return 0;
  } catch (error) {
    const code = errorCode(error);
    const failure = {
      ok: false,
      ...(flags ? { command: flags.command } : {}),
      error: {
        code,
        ...errorProvenance(error),
        message:
          error instanceof SessionImportError
            ? error.message
            : 'The guidance request could not be completed safely.',
        ...(error instanceof SessionImportError && error.replayCommand
          ? { replayCommand: error.replayCommand }
          : {}),
      },
    };
    if (flags?.json ?? argv.includes('--json'))
      io.stdout(`${JSON.stringify(failure)}\n`);
    else
      io.stderr(
        `error: ${code}${error instanceof SessionImportError ? `: ${error.message}${error.replayCommand ? `\n${error.replayCommand}` : ''}` : ''}\n`,
      );
    return code === 'unexpected-failure' ? 4 : 2;
  }
}

function runtimeFor(candidate: GuidanceSessionCandidate): Runtime {
  if (candidate.provider === 'claude') return 'claude-code';
  return candidate.provider;
}

function providerForKey(key: GuidanceQualifiedSessionId): GuidanceProvider {
  return key.slice(0, key.indexOf(':')) as GuidanceProvider;
}

async function rawMatch(
  source: string,
  selected: GuidanceSessionCandidate,
): Promise<TranscriptCandidate> {
  const runtime = runtimeFor(selected);
  let raw: TranscriptCandidate[];
  try {
    raw = await discover(
      runtime,
      source,
      new ClassificationCache(),
      runtime === 'cursor'
        ? GUIDANCE_DISCOVERY_OPTIONS
        : {
            ...GUIDANCE_DISCOVERY_OPTIONS,
            unattributablePolicy: 'summarize',
          },
    );
  } catch {
    throw Object.assign(new Error('preview-incomplete'), {
      code: 'preview-incomplete',
    });
  }
  const matches: TranscriptCandidate[] = [];
  for (const candidate of raw) {
    if (candidate.recordedCwd === null) continue;
    const recorded = await realpath(candidate.recordedCwd).catch(() => null);
    if (recorded !== selected.recordedCwd) continue;
    const nativeId =
      selected.provider === 'codex'
        ? await readGuidanceCodexNativeId(candidate)
        : candidate.sessionId;
    if (nativeId === selected.nativeId) matches.push(candidate);
  }
  if (matches.length !== 1) {
    throw Object.assign(new Error('preview-incomplete'), {
      code: 'preview-incomplete',
    });
  }
  return matches[0];
}

async function defaultPreview(source: string, key: GuidanceQualifiedSessionId) {
  const candidates = await discoverGuidanceCandidates(source, {
    providers: [providerForKey(key)],
  });
  const selected = selectGuidanceCandidate(candidates, key);
  const raw = await rawMatch(selected.recordedCwd, selected);
  const diagnostics: string[] = [];
  const bounded = await readTailRecordsBounded(raw.transcriptPath, {
    maxBytes: 2 * 1024 * 1024,
    maxRecords: 10_000,
    maxInspectedRecords: 10_000,
    deadlineMs: 10_000,
    diagnostic: ({ code }) => diagnostics.push(code),
  });
  if (diagnostics.length > 0 || bounded.recordLimitExceeded === true) {
    throw Object.assign(new Error('preview-incomplete'), {
      code: 'preview-incomplete',
    });
  }
  const entries = sanitizePreviewConversationEntries(
    runtimeFor(selected),
    normalizeEntries(runtimeFor(selected), bounded.records, {
      includeToolCalls: false,
      includeToolResults: false,
      includeCommandMessages: false,
    }),
  );
  const retained = entries.slice(-8);
  let remaining = 4_000;
  let entryTextTrimmed = false;
  const limited = retained
    .toReversed()
    .flatMap((entry) => {
      if (remaining === 0) return [];
      const text = entry.text.slice(-remaining);
      if (text.length < entry.text.length) entryTextTrimmed = true;
      remaining -= text.length;
      return [{ ...entry, text }];
    })
    .toReversed();
  return {
    key,
    entries: limited,
    truncated:
      bounded.truncated || limited.length < entries.length || entryTextTrimmed,
    warning: 'hidden-payload-sanitized-not-secret-free',
  };
}

async function defaultImport(input: SessionImportInput, digest?: string) {
  return digest === undefined
    ? planSessionImport(input)
    : applySessionImport(input, digest);
}

const DEFAULT_DEPENDENCIES: GuidanceCliDependencies = {
  import: defaultImport,
  discover: async (source, selectedProvider) =>
    discoverGuidance(source, {
      providers: selectedProvider === 'all' ? undefined : [selectedProvider],
    }),
  preview: defaultPreview,
  prepare: async (source, target, key, selectedEntryPoint) => {
    const candidates = await discoverGuidanceCandidates(source, {
      providers: [providerForKey(key)],
    });
    const candidate = selectGuidanceCandidate(candidates, key);
    return prepareForkGuidance({
      sourcePath: source,
      destinationPath: target,
      entryPoint: selectedEntryPoint,
      candidate,
    });
  },
};

import { execFile } from 'node:child_process';
import {
  mkdir,
  mkdtemp,
  readFile,
  realpath,
  rm,
  writeFile,
} from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { promisify } from 'node:util';

import { describe, expect, it, vi } from 'vitest';

import {
  runGuidanceCli,
  type GuidanceCliDependencies,
  type GuidanceCliIo,
} from './guidance-cli.js';
import { GuidanceDiscoveryError } from './guidance-discovery.js';

const execFileAsync = promisify(execFile);

function harness() {
  const stdout: string[] = [];
  const stderr: string[] = [];
  const io: GuidanceCliIo = {
    stdout: (value) => stdout.push(value),
    stderr: (value) => stderr.push(value),
  };
  const dependencies: GuidanceCliDependencies = {
    discover: vi.fn(async () => ({ candidates: [], unattributable: [] })),
    preview: vi.fn(async () => []),
    prepare: vi.fn(async () => ({ status: 'experimental-not-released' })),
  };
  return { io, dependencies, stdout, stderr };
}

describe('experimental guidance CLI', () => {
  it('exposes discovery, preview, preparation, and bounded import', async () => {
    const test = harness();
    expect(await runGuidanceCli(['--help'], test.dependencies, test.io)).toBe(
      0,
    );
    const help = test.stdout.join('');
    expect(help).toContain('discover --source');
    expect(help).toContain('preview --source');
    expect(help).toContain('prepare --source');
    expect(help).toContain('import --source');
    expect(help).toContain('--apply --expect-plan SHA256');
    expect(help).toContain('EXPERIMENTAL / NOT RELEASED');
    expect(help).not.toMatch(
      /\bexecute\b|behavior-verify|reconcile|behavior-plan/,
    );
  });

  it('routes discovery for all providers without inferring current identity', async () => {
    const test = harness();
    expect(
      await runGuidanceCli(
        ['discover', '--source', '/repo/source', '--provider', 'all', '--json'],
        test.dependencies,
        test.io,
      ),
    ).toBe(0);
    expect(test.dependencies.discover).toHaveBeenCalledWith(
      '/repo/source',
      'all',
    );
    expect(JSON.parse(test.stdout[0])).toMatchObject({
      ok: true,
      command: 'discover',
      status: 'experimental-not-released',
      currentSelection: 'explicit-required',
      data: { candidates: [], unattributable: [] },
    });
  });

  it('reports path-free provider and stable discovery failure provenance', async () => {
    const test = harness();
    vi.mocked(test.dependencies.discover).mockRejectedValue(
      new GuidanceDiscoveryError(
        'discovery-incomplete',
        'codex',
        'DISCOVERY_BYTE_BUDGET_EXCEEDED',
      ),
    );

    expect(
      await runGuidanceCli(
        [
          'discover',
          '--source',
          '/private/source-worktree',
          '--provider',
          'codex',
          '--json',
        ],
        test.dependencies,
        test.io,
      ),
    ).toBe(2);
    expect(JSON.parse(test.stdout[0])).toMatchObject({
      ok: false,
      error: {
        code: 'discovery-incomplete',
        provider: 'codex',
        reason: 'DISCOVERY_BYTE_BUDGET_EXCEEDED',
      },
    });
    expect(test.stdout.join('')).not.toContain('/private/source-worktree');
    expect(test.stdout.join('')).not.toContain('synthetic-session-id');
    expect(test.stdout.join('')).not.toContain('transcript content');
  });

  it('requires an explicit qualified source for preview and prepare', async () => {
    const preview = harness();
    expect(
      await runGuidanceCli(
        [
          'preview',
          '--source',
          '/repo/source',
          '--session',
          'codex:cli:source-id',
          '--json',
        ],
        preview.dependencies,
        preview.io,
      ),
    ).toBe(0);
    expect(preview.dependencies.preview).toHaveBeenCalledWith(
      '/repo/source',
      'codex:cli:source-id',
    );

    const prepare = harness();
    expect(
      await runGuidanceCli(
        [
          'prepare',
          '--source',
          '/repo/source',
          '--target',
          '/repo/target',
          '--session',
          'claude:cli:source-id',
          '--entry-point',
          'destination-fresh',
          '--json',
        ],
        prepare.dependencies,
        prepare.io,
      ),
    ).toBe(0);
    expect(prepare.dependencies.prepare).toHaveBeenCalledWith(
      '/repo/source',
      '/repo/target',
      'claude:cli:source-id',
      'destination-fresh',
    );
  });

  it.each([
    ['source-current', 'codex:cli:00000000-0000-4000-8000-000000000001'],
    ['source-other', 'claude:cli:00000000-0000-4000-8000-000000000002'],
    ['destination-fresh', 'codex:cli:00000000-0000-4000-8000-000000000003'],
    ['destination-fresh', 'cursor:ambiguous:synthetic-cursor-session'],
  ] as const)(
    'routes the %s entry point for %s without invoking a provider',
    async (entryPoint, qualifiedSession) => {
      const test = harness();

      expect(
        await runGuidanceCli(
          [
            'prepare',
            '--source',
            '/synthetic/source',
            '--target',
            '/synthetic/destination',
            '--session',
            qualifiedSession,
            '--entry-point',
            entryPoint,
            '--json',
          ],
          test.dependencies,
          test.io,
        ),
      ).toBe(0);
      expect(test.dependencies.prepare).toHaveBeenCalledOnce();
      expect(test.dependencies.prepare).toHaveBeenCalledWith(
        '/synthetic/source',
        '/synthetic/destination',
        qualifiedSession,
        entryPoint,
      );
      expect(JSON.parse(test.stdout[0])).toMatchObject({
        status: 'experimental-not-released',
        noForkCreated: true,
      });
    },
  );

  it('keeps the operator-facing docs explicit about entry points and unsupported Cursor transitions', async () => {
    const skill = await readFile(
      new URL(
        '../../../../skills/session-fork-to-destination/SKILL.md',
        import.meta.url,
      ),
      'utf8',
    );
    const userGuide = await readFile(
      new URL(
        '../../../../documentation/docs/user-guide/skills/session-fork-to-destination.md',
        import.meta.url,
      ),
      'utf8',
    );

    for (const document of [skill, userGuide]) {
      expect(document).toMatch(/no fork/i);
      expect(document).toMatch(/source-current/);
      expect(document).toMatch(/source-other/);
      expect(document).toMatch(/destination-fresh/);
      expect(document).toMatch(/Cursor/);
      expect(document).toMatch(/unsupported/i);
      expect(document).toMatch(/alpha/i);
      expect(document).not.toMatch(/not released|unreleased/i);
    }
  });

  it('uses explicit supported providers in public discovery examples', async () => {
    const skill = await readFile(
      new URL(
        '../../../../skills/session-fork-to-destination/SKILL.md',
        import.meta.url,
      ),
      'utf8',
    );
    const userGuide = await readFile(
      new URL(
        '../../../../documentation/docs/user-guide/skills/session-fork-to-destination.md',
        import.meta.url,
      ),
      'utf8',
    );

    for (const document of [skill, userGuide]) {
      expect(document).not.toMatch(/discover[^\n]*--provider all/);
      // The skill's example wraps the command across lines, so the provider flag
      // is allowed to follow the subcommand on a continuation line.
      expect(document).toMatch(
        /discover[\s\S]{0,160}--provider (?:claude|codex)/,
      );
      expect(document).toMatch(/`--provider all`[^.]*fail(?:s)? closed/is);
    }
  });

  it('states that current Cursor discovery cannot produce selectable candidates', async () => {
    const skill = await readFile(
      new URL(
        '../../../../skills/session-fork-to-destination/SKILL.md',
        import.meta.url,
      ),
      'utf8',
    );
    const providerGuidance = await readFile(
      new URL(
        '../../../../skills/session-fork-to-destination/references/provider-guidance.md',
        import.meta.url,
      ),
      'utf8',
    );
    const userGuide = await readFile(
      new URL(
        '../../../../documentation/docs/user-guide/skills/session-fork-to-destination.md',
        import.meta.url,
      ),
      'utf8',
    );

    for (const document of [skill, providerGuidance, userGuide]) {
      expect(document).toMatch(/independent exact cwd evidence/i);
      expect(document).toMatch(/discovery-incomplete/);
      expect(document).toMatch(
        /no Cursor candidate can be selected\s+or\s+previewed/i,
      );
      expect(document).not.toMatch(/An ambiguous Cursor candidate/i);
    }
  });

  it('resolves every shipped command from the installed skill directory', async () => {
    const skill = await readFile(
      new URL(
        '../../../../skills/session-fork-to-destination/SKILL.md',
        import.meta.url,
      ),
      'utf8',
    );

    const invocations = [
      ...skill.matchAll(/\bnode\s+([^\n]*?session-fork-to-destination\.mjs)/gu),
    ];
    expect(invocations.length).toBeGreaterThan(0);
    for (const invocation of invocations) {
      expect(invocation[1]).toBe(
        '<skill-dir>/scripts/session-fork-to-destination.mjs',
      );
    }
  });

  it('does not discover or preview a Cursor transcript through colliding lossy worktree slugs', async () => {
    const createdRoot = await mkdtemp(
      join(tmpdir(), 'handoff-cursor-collision-'),
    );
    const root = await realpath(createdRoot);
    const previousHome = process.env.HOME;
    const sourceA = join(root, 'repo', 'a-b', 'c');
    const sourceB = join(root, 'repo', 'a', 'b-c');
    const encodeCursorCwd = (cwd: string) =>
      cwd.split(/[/.]/u).filter(Boolean).join('-');
    expect(encodeCursorCwd(sourceA)).toBe(encodeCursorCwd(sourceB));

    const transcriptDir = join(
      root,
      '.cursor',
      'projects',
      encodeCursorCwd(sourceA),
      'agent-transcripts',
      'collision-session',
    );
    await mkdir(sourceA, { recursive: true });
    await mkdir(sourceB, { recursive: true });
    await mkdir(transcriptDir, { recursive: true });
    await writeFile(
      join(transcriptDir, 'conversation.jsonl'),
      `${JSON.stringify({ role: 'user', message: { content: 'COLLISION_PRIVATE_MARKER' } })}\n`,
      'utf8',
    );
    process.env.HOME = root;

    try {
      for (const source of [sourceA, sourceB]) {
        const discovery = harness();
        expect(
          await runGuidanceCli(
            ['discover', '--source', source, '--provider', 'cursor', '--json'],
            undefined,
            discovery.io,
          ),
        ).toBe(2);
        expect(discovery.stdout.join('')).toContain('discovery-incomplete');
        expect(discovery.stdout.join('')).not.toContain(source);
        expect(discovery.stdout.join('')).not.toContain(
          'COLLISION_PRIVATE_MARKER',
        );

        const preview = harness();
        expect(
          await runGuidanceCli(
            [
              'preview',
              '--source',
              source,
              '--session',
              'cursor:ambiguous:collision-session',
              '--json',
            ],
            undefined,
            preview.io,
          ),
        ).toBe(2);
        expect(preview.stdout.join('')).toContain('discovery-incomplete');
