        if (r[key] !== undefined && r[key] !== null) string(r[key]);
      if (r.uuid !== undefined) {
        const id = string(r.uuid);
        if (nodes.has(id)) refuse('duplicate-native-id');
        nodes.set(id, r);
      }
    }
    const leaf = records.findLast(
      (r) =>
        (r.type === 'user' || r.type === 'assistant') && r.isSidechain !== true,
    );
    if (
      !leaf ||
      leaf.sessionId !== selectedId ||
      (await realpath(string(leaf.cwd)).catch(() => null)) !== selectedCwd
    )
      refuse('source-identity-conflict');
    if (leaf.type === 'assistant') {
      for (const flag of [
        'isApiErrorMessage',
        'isAbortedMidStream',
        'truncatedAfterOutput',
      ]) {
        if (leaf[flag] !== undefined && typeof leaf[flag] !== 'boolean')
          refuse('malformed-native-history');
        if (leaf[flag] === true) refuse('incomplete-source-turn', REMEDY);
      }
      if (object(leaf.message).model === '<synthetic>')
        refuse('incomplete-source-turn', REMEDY);
    }
    const chain: Record<string, unknown>[] = [];
    const seen = new Set<string>();
    let node: Record<string, unknown> | undefined = leaf;
    while (node) {
      checkDeadline(deadline);
      const id = string(node.uuid);
      if (seen.has(id)) refuse('native-parent-cycle');
      seen.add(id);
      chain.push(node);
      if (node.isSidechain === true) refuse('invalid-active-chain');
      if (node.subtype === 'compact_boundary') {
        count(h, 'surviving-compaction-context');
        break;
      }
      if (node.parentUuid === null || node.parentUuid === undefined) break;
      node = nodes.get(string(node.parentUuid));
      if (!node) refuse('native-parent-missing');
    }
    chain.reverse();
    const calls = new Map<string, string>();
    const results = new Set<string>();
    for (const r of chain) {
      const m = r.message;
      if (m === undefined) continue;
      const content = object(m).content;
      if (!Array.isArray(content)) continue;
      for (const raw of content) {
        const b = object(raw);
        if (b.type === 'tool_use') calls.set(toolId(b.id), string(r.uuid));
        if (b.type === 'tool_result') results.add(toolId(b.tool_use_id));
      }
    }
    for (const r of records) {
      if (
        r.type !== 'user' ||
        seen.has(r.uuid as string) ||
        r.isSidechain === true
      )
        continue;
      const content = object(r.message).content;
      if (
        Array.isArray(content) &&
        content.length &&
        content.every((raw) => {
          const b = object(raw);
          return (
            b.type === 'tool_result' &&
            calls.has(b.tool_use_id as string) &&
            !results.has(b.tool_use_id as string) &&
            [r.parentUuid, r.sourceToolAssistantUUID].includes(
              calls.get(b.tool_use_id as string),
            )
          );
        })
      ) {
        if (
          r.sessionId !== selectedId ||
          (await realpath(string(r.cwd)).catch(() => null)) !== selectedCwd
        )
          refuse('source-identity-conflict');
        chain.push(r);
        for (const b of content) results.add(string(object(b).tool_use_id));
      }
    }
    chain.sort((a, b) => order.get(a)! - order.get(b)!);
    checkDeadline(deadline);
    h.timestamp = stamp(
      chain.find((r) => r.timestamp !== undefined)?.timestamp,
    );
    for (const r of chain) {
      checkDeadline(deadline);
      if (r.sessionId !== undefined && r.sessionId !== selectedId) {
        const inherited = string(r.sessionId);
        h.inheritedIds.push(inherited);
        count(h, 'inherited-provenance');
      }
      if (r.cwd !== undefined && typeof r.cwd !== 'string')
        refuse('source-identity-conflict');
      if (r.type !== 'user' && r.type !== 'assistant') {
        if (
          r.type === 'system' &&
          r.subtype !== 'compact_boundary' &&
          r.subtype !== 'local_command' &&
          r.subtype !== 'turn_duration' &&
          r.subtype !== 'stop_hook_summary'
        )
          refuse('unsupported-native-control');
        count(h, 'runtime-context');
        continue;
      }
      const m = object(r.message);
      if (m.role !== r.type) refuse('malformed-native-history');
      if (r.isMeta === true) {
        count(h, 'runtime-context');
        continue;
      }
      const blocks =
        typeof m.content === 'string'
          ? [{ type: 'text', text: m.content }]
          : m.content;
      if (!Array.isArray(blocks)) refuse('malformed-native-history');
      for (const raw of blocks) {
        const b = object(raw);
        if (b.type === 'thinking' || b.type === 'redacted_thinking') {
          count(h, 'private-reasoning');
          continue;
        }
        if (b.type === 'tool_use') {
          if (r.type !== 'assistant') refuse('malformed-native-history');
          h.items.push({
            kind: 'call',
            callKind: 'function_call',
            id: toolId(b.id),
            name: toolName(b.name),
            arguments: argumentsObject(b.input),
          });
        } else if (b.type === 'tool_result') {
          if (
            r.type !== 'user' ||
            (b.is_error !== undefined && typeof b.is_error !== 'boolean')
          )
            refuse('malformed-native-history');
          h.items.push({
            kind: 'result',
            callKind: 'function_call',
            id: toolId(b.tool_use_id),
            output: output(b.content, h),
            ...(b.is_error === undefined
              ? {}
              : { isError: b.is_error as boolean }),
          });
        } else {
          const text = textContent([b], r.type, h, 'claude');
          if (text.length) h.items.push({ kind: 'text', role: r.type, text });
        }
      }
    }
  }
  validateHistory(h);
  h.inheritedIds = [...new Set(h.inheritedIds)];
  return h;
}
export function deterministicUuid(value: string): string {
  const b = createHash('sha256').update(value).digest().subarray(0, 16);
  b[6] = (b[6] & 15) | 128;
  b[8] = (b[8] & 63) | 128;
  const s = b.toString('hex');
  return `${s.slice(0, 8)}-${s.slice(8, 12)}-${s.slice(12, 16)}-${s.slice(16, 20)}-${s.slice(20)}`;
}
export function encodeNativeHistory(
  provider: ImportProvider,
  h: NativeHistory,
  id: string,
  cwd: string,
  provenance: Record<string, unknown>,
): string {
  const rows: Record<string, unknown>[] = [];
  if (provider === 'codex') {
    rows.push({
      type: 'session_meta',
      timestamp: h.timestamp,
      payload: {
        id,
        timestamp: h.timestamp,
        cwd,
        originator: 'session-fork-to-destination',
        cli_version: '0.3.0',
        source: 'cli',
        history_mode: 'legacy',
        session_import: provenance,
      },
    });
    const calls = new Map<string, Extract<HistoryItem, { kind: 'call' }>>();
    for (const item of h.items) {
      let p: Record<string, unknown>;
      let event: Record<string, unknown>;
      if (item.kind === 'text') {
        p = {
          type: 'message',
          role: item.role,
          content: [
            {
              type: item.role === 'user' ? 'input_text' : 'output_text',
              text: item.text,
            },
          ],
          ...(item.phase ? { phase: item.phase } : {}),
        };
        event = {
          type: item.role === 'user' ? 'user_message' : 'agent_message',
          message: item.text,
          ...(item.role === 'user'
            ? { images: [], local_images: [], text_elements: [] }
            : { phase: item.phase ?? 'final_answer' }),
        };
      } else if (item.kind === 'call') {
        calls.set(item.id, item);
        p = {
          type: item.callKind,
          call_id: item.id,
          name: item.name,
          ...(item.namespace ? { namespace: item.namespace } : {}),
          ...(item.callKind === 'function_call'
            ? { arguments: item.arguments }
            : { input: item.arguments }),
        };
        event = {
          type: 'mcp_tool_call_begin',
          call_id: item.id,
          turn_id: '',
          invocation: {
            server: 'imported_history',
            tool: item.name,
            arguments:
              item.callKind === 'function_call'
                ? JSON.parse(item.arguments)
                : { input: item.arguments },
          },
        };
      } else {
        const out = item.isError
          ? typeof item.output === 'string'
            ? `[Tool error]\n${item.output}`
            : [{ type: 'input_text', text: '[Tool error]' }, ...item.output]
          : item.output;
        p = { type: `${item.callKind}_output`, call_id: item.id, output: out };
        const call = calls.get(item.id)!;
        event = {
          type: 'mcp_tool_call_end',
          call_id: item.id,
          turn_id: '',
          invocation: {
            server: 'imported_history',
            tool: call.name,
            arguments:
              call.callKind === 'function_call'
                ? JSON.parse(call.arguments)
                : { input: call.arguments },
          },
          result: {
            Ok: {
              content:
                typeof out === 'string'
                  ? [{ type: 'text', text: out }]
                  : out.map((b) => ({ type: 'text', text: b.text })),
              isError: item.isError ?? false,
            },
          },
          duration: { secs: 0, nanos: 0 },
        };
      }
      rows.push(
        { type: 'response_item', timestamp: h.timestamp, payload: p },
        { type: 'event_msg', timestamp: h.timestamp, payload: event },
      );
    }
  } else {
    const groups: Array<{ role: 'user' | 'assistant'; items: HistoryItem[] }> =
      [];
    for (const item of h.items) {
      const role =
        item.kind === 'text'
          ? item.role
          : item.kind === 'call'
            ? 'assistant'
            : 'user';
      if (groups.at(-1)?.role === role) groups.at(-1)!.items.push(item);
      else groups.push({ role, items: [item] });
    }
    let parent: string | null = null;
    groups.forEach((g, index) => {
      const uuid = deterministicUuid(`${id}:${index}`);
      const content = g.items.map((item) =>
        item.kind === 'text'
          ? { type: 'text', text: item.text }
          : item.kind === 'call'
            ? {
                type: 'tool_use',
                id: item.id,
                name: item.name,
                input:
                  item.callKind === 'function_call'
                    ? JSON.parse(item.arguments)
                    : { input: item.arguments },
              }
            : {
                type: 'tool_result',
                tool_use_id: item.id,
                content:
                  typeof item.output === 'string'
                    ? item.output
                    : item.output.map((b) => ({ type: 'text', text: b.text })),
                ...(item.isError === undefined
                  ? {}
                  : { is_error: item.isError }),
              },
      );
      const message = {
        role: g.role,
        content,
        ...(g.role === 'assistant'
          ? {
              id: `msg_${uuid.replaceAll('-', '')}`,
              type: 'message',
              model: 'imported',
              stop_reason: g.items.some((i) => i.kind === 'call')
                ? 'tool_use'
                : 'end_turn',
              stop_sequence: null,
              usage: { input_tokens: 0, output_tokens: 0 },
            }
          : {}),
      };
      rows.push({
        type: g.role,
        uuid,
        parentUuid: parent,
        sessionId: id,
        cwd,
        timestamp: h.timestamp,
        isSidechain: false,
        userType: 'external',
        entrypoint: 'cli',
        version: '0.3.0',
        message,
        ...(index === 0 ? { session_import: provenance } : {}),
      });
      parent = uuid;
    });
  }
  return rows.map((row) => JSON.stringify(row)).join('\n') + '\n';
}

export class SessionImportError extends Error {
  constructor(
    readonly code: string,
    message = code,
    readonly replayCommand?: string,
  ) {
    super(message);
    this.name = 'SessionImportError';
  }
}
export function refuse(code: string, message?: string): never {
  throw new SessionImportError(code, message);
}
export const IMPORT_MAX_BYTES = 32 * 1024 * 1024;
export function checkDeadline(deadline: number): void {
  if (Date.now() >= deadline) refuse('import-limit-exceeded');
}
export function object(value: unknown): Record<string, unknown> {
  if (value === null || typeof value !== 'object' || Array.isArray(value))
    refuse('malformed-native-history');
  return value as Record<string, unknown>;
}
export function string(value: unknown): string {
  if (typeof value !== 'string') refuse('malformed-native-history');
  return value;
}

import { createHash, randomUUID } from 'node:crypto';
import { constants } from 'node:fs';
import {
  link,
  lstat,
  mkdir,
  open,
  opendir,
  realpath,
  unlink,
} from 'node:fs/promises';
import { dirname, join, relative, sep } from 'node:path';

import {
  checkDeadline,
  IMPORT_MAX_BYTES,
  object,
  refuse,
  SessionImportError,
} from './import-errors.js';
import type { ImportProvider } from './native-history.js';
export const sha256 = (value: string | Buffer): string =>
  createHash('sha256').update(value).digest('hex');
export interface SourceSnapshot {
  bytes: Buffer;
  records: Record<string, unknown>[];
  digest: string;
  identity: {
    dev: string;
    ino: string;
    size: string;
    mtimeNs: string;
    ctimeNs: string;
  };
}
export async function readImportSnapshot(
  path: string,
  deadline: number,
): Promise<SourceSnapshot> {
  checkDeadline(deadline);
  let file;
  try {
    file = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  } catch {
    refuse('source-unreadable');
  }
  try {
    const before = await file.stat({ bigint: true });
    if (!before.isFile()) refuse('source-unreadable');
    if (before.size > BigInt(IMPORT_MAX_BYTES)) refuse('import-limit-exceeded');
    const bytes = Buffer.alloc(Number(before.size));
    let offset = 0;
    while (offset < bytes.length) {
      checkDeadline(deadline);
      const read = await file.read(
        bytes,
        offset,
        bytes.length - offset,
        offset,
      );
      if (!read.bytesRead) refuse('source-snapshot-changed');
      offset += read.bytesRead;
    }
    const after = await file.stat({ bigint: true });
    const identity = {
      dev: String(before.dev),
      ino: String(before.ino),
      size: String(before.size),
      mtimeNs: String(before.mtimeNs),
      ctimeNs: String(before.ctimeNs),
    };
    if (
      before.dev !== after.dev ||
      before.ino !== after.ino ||
      before.size !== after.size ||
      before.mtimeNs !== after.mtimeNs ||
      before.ctimeNs !== after.ctimeNs
    )
      refuse('source-snapshot-changed');
    let text;
    try {
      text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    } catch {
      refuse('malformed-native-history');
    }
    if (!text.endsWith('\n')) refuse('malformed-native-history');
    const lines = text.slice(0, -1).split('\n');
    if (lines.length > 100_000) refuse('import-limit-exceeded');
    const records = lines.map((line) => {
      checkDeadline(deadline);
      if (Buffer.byteLength(line) > 4 * 1024 * 1024)
        refuse('import-limit-exceeded');
      try {
        return object(JSON.parse(line));
      } catch (error) {
        if (error instanceof SessionImportError) throw error;
        refuse('malformed-native-history');
      }
    });
    return { bytes, records, digest: sha256(bytes), identity };
  } finally {
    await file.close();
  }
}
export async function revalidateImportSnapshot(
  path: string,
  snapshot: SourceSnapshot,
  deadline: number,
): Promise<void> {
  const current = await readImportSnapshot(path, deadline);
  if (
    current.digest !== snapshot.digest ||
    JSON.stringify(current.identity) !== JSON.stringify(snapshot.identity)
  )
    refuse('source-snapshot-changed');
}
export type ImportOccupancy = 'absent' | 'exact' | 'diverged' | 'archived';
function within(home: string, path: string): void {
  const rel = relative(home, path);
  if (!rel || rel === '..' || rel.startsWith(`..${sep}`) || rel.startsWith(sep))
    refuse('invalid-store-path');
}
async function exists(path: string) {
  try {
    return await lstat(path, { bigint: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw error;
  }
}
async function storeWrite<T>(operation: () => Promise<T>): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === 'EACCES' || code === 'EPERM')
      throw new SessionImportError('store-write-denied');
    throw error;
  }
}
async function inspectParents(
  home: string,
  path: string,
  create: boolean,
  deadline: number,
): Promise<Array<{ path: string; dev: bigint; ino: bigint }>> {
  within(home, path);
  const parts = relative(home, dirname(path)).split(sep).filter(Boolean);
  const parents = [];
  let current = home;
  const root = await lstat(home, { bigint: true });
  if (
    !root.isDirectory() ||
    root.isSymbolicLink() ||
    (await realpath(home)) !== home
  )
    refuse('store-path-drift');
  parents.push({ path: home, dev: root.dev, ino: root.ino });
  for (const part of parts) {
    checkDeadline(deadline);
    current = join(current, part);
    let stat = await exists(current);
    if (!stat && create) {
      try {
        await storeWrite(() => mkdir(current, { mode: 0o700 }));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
      }
      stat = await exists(current);
    }
    if (!stat) break;
    if (!stat.isDirectory() || stat.isSymbolicLink())
      refuse('unsafe-store-path');
    parents.push({ path: current, dev: stat.dev, ino: stat.ino });
  }
  return parents;
}
async function matchesBytes(
  path: string,
  bytes: Buffer,
  deadline: number,
): Promise<boolean> {
  checkDeadline(deadline);
  const stat = await exists(path);
  if (!stat) return false;
  if (!stat.isFile() || stat.isSymbolicLink()) refuse('unsafe-store-path');
  if (stat.size !== BigInt(bytes.length)) return false;
  let file;
  try {
    file = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
    const opened = await file.stat({ bigint: true });
    if (
      !opened.isFile() ||
      opened.dev !== stat.dev ||
      opened.ino !== stat.ino ||
      opened.size !== stat.size ||
      opened.mtimeNs !== stat.mtimeNs ||
      opened.ctimeNs !== stat.ctimeNs
    )
      refuse('store-path-drift');
    const existing = Buffer.alloc(bytes.length);
    let offset = 0;
    while (offset < existing.length) {
      checkDeadline(deadline);
      const read = await file.read(
        existing,
        offset,
        existing.length - offset,
        offset,
      );
      if (!read.bytesRead) refuse('store-path-drift');
      offset += read.bytesRead;
    }
    const after = await file.stat({ bigint: true });
    if (
      after.size !== opened.size ||
      after.mtimeNs !== opened.mtimeNs ||
      after.ctimeNs !== opened.ctimeNs
    )
      refuse('store-path-drift');
    return existing.equals(bytes);
  } finally {
    await file?.close();
  }
}
async function enumerateMatches(
  dir: string,
  id: string,
  deadline: number,
  recursive: boolean,
  counter: { value: number },
  matches: string[],
): Promise<void> {
  checkDeadline(deadline);
  const stat = await exists(dir);
  if (!stat) return;
  if (!stat.isDirectory() || stat.isSymbolicLink()) refuse('unsafe-store-path');
  const handle = await opendir(dir);
  for await (const entry of handle) {
    checkDeadline(deadline);
    if (++counter.value > 50_000) refuse('import-limit-exceeded');
    const path = join(dir, entry.name);
    if (entry.isSymbolicLink()) {
      if (entry.name.endsWith(`${id}.jsonl`) || recursive)
        refuse('unsafe-store-path');
      continue;
    }
    if (entry.name.endsWith(`-${id}.jsonl`)) matches.push(path);
    if (recursive && entry.isDirectory())
      await enumerateMatches(path, id, deadline, true, counter, matches);
  }
}
export async function inspectImportOccupancy(
  home: string,
  path: string,
  id: string,
  provider: ImportProvider,
  bytes: Buffer,
  deadline: number,
): Promise<ImportOccupancy> {
  await inspectParents(home, path, false, deadline);
  if (provider === 'codex') {
    const counter = { value: 0 };
    const archives: string[] = [];
    await enumerateMatches(
      join(home, 'archived_sessions'),
      id,
      deadline,
      true,
      counter,
      archives,
    );
    if (archives.length) return 'archived';
    const active: string[] = [];
    await enumerateMatches(dirname(path), id, deadline, false, counter, active);
    if (active.some((p) => p !== path)) return 'diverged';
  }
  const stat = await exists(path);
  if (!stat) return 'absent';
  return (await matchesBytes(path, bytes, deadline)) ? 'exact' : 'diverged';
}
export async function publishImportSeed(
  home: string,
  path: string,
  id: string,
  provider: ImportProvider,
  bytes: Buffer,
  deadline: number,
  revalidate: () => Promise<void>,
): Promise<'imported' | 'already-imported'> {
  let temporary: string | undefined;
  let published = false;
  let ownsTemporary = false;
  const publish = async (): Promise<'imported' | 'already-imported'> => {
    try {
      const occupancy = await inspectImportOccupancy(
        home,
        path,
        id,
        provider,
        bytes,
        deadline,
      );
      if (occupancy === 'exact') {
        await revalidate();
        const current = await inspectImportOccupancy(
          home,
          path,
          id,
          provider,
          bytes,
          deadline,
        );
        if (current !== 'exact')
          refuse(current === 'archived' ? 'seed-archived' : 'seed-diverged');
        return 'already-imported';
      }
      if (occupancy === 'archived')
        refuse(
          'seed-archived',
          'Restore the seed through the provider archive workflow, then replan.',
        );
      if (occupancy === 'diverged')
        refuse(
          'seed-diverged',
          'The existing seed evolved. Manually fork that seed if its additional history is wanted.',
        );
      const parents = await inspectParents(home, path, true, deadline);
      const stagingPath = join(
        dirname(path),
        `.session-import-${randomUUID()}.tmp`,
      );
      temporary = stagingPath;
      const file = await storeWrite(() =>
        open(
          stagingPath,
          constants.O_WRONLY |
            constants.O_CREAT |
            constants.O_EXCL |
            constants.O_NOFOLLOW,
          0o600,
        ),
      );
      ownsTemporary = true;
      try {
        await storeWrite(() => file.writeFile(bytes));
        await storeWrite(() => file.sync());
      } finally {
        await file.close();
      }
      await revalidate();
      checkDeadline(deadline);
      for (const expected of parents) {
        const actual = await lstat(expected.path, { bigint: true });
        if (
          !actual.isDirectory() ||
          actual.isSymbolicLink() ||
          actual.dev !== expected.dev ||
          actual.ino !== expected.ino
        )
          refuse('store-path-drift');
      }
      const now = await inspectImportOccupancy(
        home,
        path,
        id,
        provider,
        bytes,
        deadline,
      );
      if (now === 'archived') refuse('seed-archived');
      if (now === 'diverged') refuse('seed-diverged');
      if (now === 'exact') return 'already-imported';
      try {
        await storeWrite(() => link(stagingPath, path));
        published = true;
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'EEXIST') {
          if (await matchesBytes(path, bytes, deadline))
            return 'already-imported';
          refuse('seed-diverged');
        }
        if (
          ['ENOTSUP', 'EOPNOTSUPP', 'EXDEV'].includes(
            (error as NodeJS.ErrnoException).code ?? '',
          )
        )
          throw new SessionImportError('store-publication-unsupported');
        throw error;
      }
      const dir = await open(dirname(path), constants.O_RDONLY);
      try {
        await dir.sync();
      } finally {
        await dir.close();
      }
      return 'imported';
    } catch (error) {
      if (published)
        throw new SessionImportError(
          'seed-published-durability-failed',
          'The seed was published, but durability verification failed. Exact bytes are safe to retry.',
        );
      throw error;
    }
  };
  let result: 'imported' | 'already-imported' | undefined;
  let failure: unknown;
  try {
    result = await publish();
  } catch (error) {
    failure = error;
  }
  if (temporary && ownsTemporary) {
    try {
      await unlink(temporary);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
        const cleanupFailure = new SessionImportError(
          published ? 'seed-published-cleanup-failed' : 'store-cleanup-failed',
          'Owned staging-file cleanup failed; inspect the destination directory before retrying.',
        );
        if (failure === undefined) throw cleanupFailure;
        if (failure instanceof Error)
          failure.message += ` Secondary cleanup failure (${cleanupFailure.code}): ${cleanupFailure.message}`;
      }
    }
  }
  if (failure !== undefined) throw failure;
  return result!;
}

